class Solution {
public:
    long long appealSum(string s) {
        long long ans = 0, running = 0;
        int last[26];
        for (int i = 0; i < 26; i++) last[i] = -1;
        for (int i = 0; i < (int)s.size(); i++) {
            int c = s[i] - 'a';
            running += i - last[c];
            ans += running;
            last[c] = i;
        }
        return ans;
    }
};
